class Solution {
  private static int compare(int[] a, int ac, int[] b, int bc) {
    for (int i = 0; i < Math.min(ac, bc); i++) {
      if (a[i] != b[i]) return Integer.compare(a[i], b[i]);
    }
    return Integer.compare(ac, bc);
  }

  public int[] maximumWeight(List<List<Integer>> intervals) {
    int n = intervals.size();
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    java.util.Arrays.sort(
        order, (a, b) -> Integer.compare(intervals.get(a).get(0), intervals.get(b).get(0)));
    int[] l = new int[n], r = new int[n], w = new int[n];
    for (int i = 0; i < n; i++) {
      List<Integer> iv = intervals.get(order[i]);
      l[i] = iv.get(0);
      r[i] = iv.get(1);
      w[i] = iv.get(2);
    }
    int[] nxt = new int[n];
    for (int i = 0; i < n; i++) {
      int lo = i + 1, hi = n;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (l[mid] > r[i]) hi = mid;
        else lo = mid + 1;
      }
      nxt[i] = lo;
    }
    long[][] score = new long[5][n + 1];
    int[][] cnt = new int[5][n + 1];
    int[][][] idx = new int[5][n + 1][4];
    int[] tmp = new int[4];
    for (int i = n - 1; i >= 0; i--) {
      for (int k = 1; k <= 4; k++) {
        score[k][i] = score[k][i + 1];
        cnt[k][i] = cnt[k][i + 1];
        System.arraycopy(idx[k][i + 1], 0, idx[k][i], 0, 4);
        int p = nxt[i], c = cnt[k - 1][p];
        long s = w[i] + score[k - 1][p];
        int oi = order[i], t = 0;
        boolean put = false;
        for (int q = 0; q < c; q++) {
          if (!put && oi < idx[k - 1][p][q]) {
            tmp[t++] = oi;
            put = true;
          }
          tmp[t++] = idx[k - 1][p][q];
        }
        if (!put) tmp[t++] = oi;
        if (s > score[k][i] || (s == score[k][i] && compare(tmp, t, idx[k][i], cnt[k][i]) < 0)) {
          score[k][i] = s;
          cnt[k][i] = t;
          System.arraycopy(tmp, 0, idx[k][i], 0, t);
        }
      }
    }
    return java.util.Arrays.copyOf(idx[4][0], cnt[4][0]);
  }
}
